"""Connect existing collection hubs, guides and industry routes without duplicate URLs."""
HUB_GUIDES={
 '/catalog/magnetic-boxes/':('Magnetic gift-box buying guide','Compare the opening experience, board construction, assembled footprint and product retention before choosing decorative finishes. A magnetic closure is a design feature; it does not establish shipping protection or a particular board specification.',[('Construction','Compare an assembled rigid structure with a collapsible direction and review the corners, hinge and closure on a sample.'),('Product retention','Specify the contents, orientation, cavity layout and removal space. Review the insert separately from the outer box.'),('Packing and delivery','Confirm whether boxes ship assembled or flat, the assembly work and the shipping carton arrangement.')],['folding-cartons-vs-rigid-boxes','cosmetic-packaging-buyers-guide'],'beauty-skincare'),
 '/catalog/drawer-boxes/':('Drawer-box buying guide','A drawer box combines a sliding tray and an outer sleeve. Define the product layout, opening direction and handling requirements before selecting paper wraps, pull details or surface finishes.',[('Tray and sleeve','Review sliding clearance, loaded fit and stops using a representative structural sample.'),('Pull detail','Compare a ribbon, tab or finger notch with the actual product weight and opening direction.'),('Presentation and transport','Check insert retention and the outer shipping protection separately from the drawer’s appearance.')],['internal-vs-external-box-dimensions','packaging-sample-types'],'gifting'),
 '/catalog/mailer-shipping-boxes/':('Mailer and shipping-box buying guide','Select a corrugated package around the packed product, internal protection and distribution route. The structure name or photograph alone does not establish board strength, load capacity or transit-test performance.',[('Structure','Compare a locking mailer with a taped shipping carton against packing speed and the intended opening experience.'),('Board and load','Specify board construction, packed weight and expected stacking; review a suitable test plan for the distribution route.'),('Fit and protection','Measure the complete retail pack, allow for cushioning and check movement with an assembled sample.')],['mailer-boxes-vs-shipping-boxes','packaging-materials-explained'],'ecommerce'),
 '/catalog/paper-bags/':('Paper-bag buying guide','Choose the bag around what it must carry, rather than paper appearance alone. Bag dimensions, handle attachment, seams and base reinforcement must be reviewed together with the intended contents and handling conditions.',[('Dimensions','Include the complete product set, insertion clearance and usable height below the handles.'),('Handles and base','Compare carrying comfort, attachment and reinforcement using the actual packed weight.'),('Surface and print','Approve artwork and finishes on the selected stock; a paper appearance is not proof of recycling or moisture resistance.')],['custom-paper-bags-guide','paper-bag-load-testing'],'apparel'),
 '/catalog/stand-up-pouches/':('Stand-up pouch buying guide','Start with the contents, filling process, shelf-life target and closure requirements. A stand-up shape does not define the barrier, seal compatibility or food-contact suitability of the final laminate.',[('Filled fit','Review fill weight or volume, bottom gusset, headspace and closure clearance with the actual product.'),('Material construction','Specify layers, thickness and barrier needs; confirm the documents and tests relevant to the selected structure.'),('Features','Review the zipper, valve, spout or tear notch as separate choices and confirm their suitability before approval.')],['stand-up-vs-flat-bottom-pouches','packaging-sample-types'],'food-snacks')}

def catalog_hub_guide(base):
 if base not in HUB_GUIDES:return ''
 title,answer,rows,guides,industry=HUB_GUIDES[base]
 return '<section class="section wrap hub-guide"><h2>'+title+'</h2><p>'+answer+'</p>'+table(rows)+'<div class="related-links">'+''.join('<a href="/guides/'+slug+'/">'+esc(TOPICS[slug][0])+'</a>' for slug in guides)+'<a href="/industries/'+industry+'/">Explore the industry solution</a><a href="/cases/">Compare coordinated design concepts</a></div></section>'

def companion_links(record):
 if record['family']=='paper-boxes':
  links=[('/catalog/molded-pulp-inserts/','Insert references'),('/catalog/paper-shopping-bags/','Paper shopping bags'),('/catalog/cards-booklets/','Cards and printed information'),('/catalog/stickers-labels/','Labels and seals')]
 elif record['family']=='bags':
  links=[('/catalog/paper-boxes/','Outer and presentation boxes'),('/catalog/stickers-labels/','Labels and seals'),('/catalog/cards-booklets/','Cards and printed information')]
 else:
  links=[('/catalog/paper-boxes/','Boxes to coordinate'),('/catalog/bags/','Bags and pouches to coordinate')]
 return '<section class="section wrap"><h2>Plan companion packaging</h2><p>Explore components for the same project. Dimensions, material compatibility, print and quantity are confirmed separately for each item; these links do not establish a tested fit.</p><div class="related-links">'+''.join('<a href="'+url+'">'+name+'</a>' for url,name in links)+'</div></section>'
